BEGIN TRANSACTION;
CREATE TABLE breaches (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  agency            TEXT NOT NULL,
  statute_section   TEXT,
  breach_type       TEXT NOT NULL,   -- missed_deadline | no_extension_notice | no_privilege_log | incomplete_production | other
  date_detected     TEXT,
  date_logged       TEXT,
  severity          INTEGER,         -- 1 (admin) .. 5 (rights-defeating)
  description       TEXT,
  request_id        TEXT REFERENCES requests(request_id),
  evidence_doc_id   TEXT,
  created_at        TEXT NOT NULL
);
CREATE TABLE chain (
  seq        INTEGER PRIMARY KEY AUTOINCREMENT,
  table_name TEXT NOT NULL,
  row_id     INTEGER NOT NULL,
  op         TEXT NOT NULL CHECK (op = 'INSERT'),
  row_hash   TEXT NOT NULL,
  prev_hash  TEXT NOT NULL,
  record_hash TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE cross_references (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  from_table  TEXT NOT NULL,
  from_id     INTEGER NOT NULL,
  to_table    TEXT NOT NULL,
  to_id       INTEGER NOT NULL,
  relation    TEXT,
  note        TEXT,
  created_at  TEXT NOT NULL
);
CREATE TABLE documents (
  seq           INTEGER PRIMARY KEY,
  doc_id        TEXT UNIQUE NOT NULL,
  title         TEXT,
  source_url    TEXT,
  sha256        TEXT NOT NULL,
  bytes         INTEGER,
  witnessed_at  TEXT,
  record_hash   TEXT
);
CREATE TABLE escalations (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  target            TEXT NOT NULL,
  instrument_type   TEXT NOT NULL,   -- petition | mandamus | creditor_objection | ombudsman_complaint | court_filing | federal_docket | agency_objection | tip_submission
  reference_number  TEXT,
  date_filed        TEXT,
  status            TEXT,
  opposing_response TEXT,
  cost              REAL,
  request_id        TEXT REFERENCES requests(request_id),
  created_at        TEXT NOT NULL
);
CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE outcomes (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id        TEXT REFERENCES requests(request_id),
  outcome_type      TEXT NOT NULL,   -- full_production | partial_production | denial | settled | court_ruled | no_response | other
  outcome_date      TEXT,
  description       TEXT,
  linked_breach_id  INTEGER REFERENCES breaches(id),
  created_at        TEXT NOT NULL
);
CREATE TABLE requests (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id          TEXT UNIQUE NOT NULL,
  agency             TEXT NOT NULL,
  jurisdiction        TEXT NOT NULL,
  statute             TEXT,
  date_submitted      TEXT,
  delivery_method     TEXT,
  records_sought      TEXT,
  response_deadline   TEXT,
  actual_response_date TEXT,
  days_overdue        INTEGER,
  request_doc_hash    TEXT,
  notes               TEXT,
  created_at          TEXT NOT NULL
);
CREATE TRIGGER no_update_requests  BEFORE UPDATE ON requests  BEGIN SELECT RAISE(ABORT,'append-only: requests'); END;
CREATE TRIGGER no_delete_requests  BEFORE DELETE ON requests  BEGIN SELECT RAISE(ABORT,'append-only: requests'); END;
CREATE TRIGGER no_update_breaches  BEFORE UPDATE ON breaches  BEGIN SELECT RAISE(ABORT,'append-only: breaches'); END;
CREATE TRIGGER no_delete_breaches  BEFORE DELETE ON breaches  BEGIN SELECT RAISE(ABORT,'append-only: breaches'); END;
CREATE TRIGGER no_update_escalations BEFORE UPDATE ON escalations BEGIN SELECT RAISE(ABORT,'append-only: escalations'); END;
CREATE TRIGGER no_delete_escalations BEFORE DELETE ON escalations BEGIN SELECT RAISE(ABORT,'append-only: escalations'); END;
CREATE TRIGGER no_update_outcomes BEFORE UPDATE ON outcomes BEGIN SELECT RAISE(ABORT,'append-only: outcomes'); END;
CREATE TRIGGER no_delete_outcomes BEFORE DELETE ON outcomes BEGIN SELECT RAISE(ABORT,'append-only: outcomes'); END;
CREATE TRIGGER no_update_xref BEFORE UPDATE ON cross_references BEGIN SELECT RAISE(ABORT,'append-only: cross_references'); END;
CREATE TRIGGER no_delete_xref BEFORE DELETE ON cross_references BEGIN SELECT RAISE(ABORT,'append-only: cross_references'); END;
DELETE FROM "sqlite_sequence";
COMMIT;
